(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[571],{3885:function(e,n,t){Promise.resolve().then(t.bind(t,8549))},8549:function(e,n,t){"use strict";t.r(n),t.d(n,{default:function(){return o}});var i=t(7573),s=t(9036),r=t(368);let a={en:{title:"Terms of use",lead:"The short version: the platform arranges the appointment, the salon delivers it, and every rule you are held to was shown before you paid.",s:[["1. Who you contract with","StyleNow operates a booking platform. The service contract for an appointment is between you and the salon named on the booking; the salon is also who issues your receipt. Platform use is free for customers."],["2. Booking",'When you pick a time, the seat is held for a few minutes while you confirm ("seat before money"). A booking exists once you complete the confirmation step and receive a reference number. Prices shown include VAT; deposits, where a salon requires one, are stated before payment.'],["3. Cancelling and moving","Each salon sets its own cancellation policy — the free-cancellation window, late-cancellation and no-show fees. The policy in force is the one shown at booking, and it is frozen onto your booking from that moment; a salon changing its rules later does not change your booking. Within the free window you can cancel or move the appointment yourself; after it, fees may apply as stated."],["4. Prices","Salons may price differently by time and demand. Every deviation from a base price is itemised on the price you accept and on your receipt. Prime flexible bookings carry their surcharge openly."],["5. Conduct","Reviews must relate to a real visit. Salons answer reviews publicly under their own name. Repeated no-shows may lead a salon to require deposits."],["6. Accounts and termination","You can delete your account yourself at any time in the Account tab; salons can disconnect their shop themselves. Statutory retention duties on issued receipts remain with the salon."],["7. Demo notice","This deployment is a demonstration. No real payments are collected and no real appointments are created."]]},de:{title:"Nutzungsbedingungen (AGB)",lead:"Die Kurzfassung: Die Plattform vermittelt den Termin, der Salon erbringt ihn, und jede Regel, an der du gemessen wirst, stand vor der Zahlung fest.",s:[["1. Mit wem du den Vertrag schlie\xdft","StyleNow betreibt eine Buchungsplattform. Der Dienstleistungsvertrag \xfcber einen Termin kommt zwischen dir und dem auf der Buchung genannten Salon zustande; der Salon stellt auch deinen Beleg aus. Die Nutzung der Plattform ist f\xfcr Kundinnen und Kunden kostenlos."],["2. Buchung",'W\xe4hlst du eine Zeit, wird der Platz f\xfcr einige Minuten gehalten, w\xe4hrend du best\xe4tigst („erst der Platz, dann das Geld"). Eine Buchung besteht, sobald du den Best\xe4tigungsschritt abschlie\xdft und eine Referenznummer erh\xe4ltst. Angezeigte Preise enthalten die USt; Anzahlungen, wo ein Salon sie verlangt, stehen vor der Zahlung fest.'],["3. Stornieren und Verschieben","Jeder Salon bestimmt seine eigenen Stornoregeln — kostenloses Stornofenster, Geb\xfchren f\xfcr sp\xe4te Absagen und Nichterscheinen. Es gilt die bei der Buchung angezeigte Regelung, und sie wird in diesem Moment in deiner Buchung eingefroren; \xe4ndert ein Salon sp\xe4ter seine Regeln, \xe4ndert das deine Buchung nicht. Im kostenlosen Fenster kannst du selbst stornieren oder verschieben; danach k\xf6nnen die genannten Geb\xfchren anfallen."],["4. Preise","Salons d\xfcrfen nach Zeit und Nachfrage unterschiedlich bepreisen. Jede Abweichung vom Grundpreis wird auf dem akzeptierten Preis und auf deinem Beleg einzeln ausgewiesen. Prime-Flexbuchungen tragen ihren Aufschlag offen."],["5. Verhalten","Bewertungen m\xfcssen sich auf einen echten Besuch beziehen. Salons antworten \xf6ffentlich unter eigenem Namen. Wiederholtes Nichterscheinen kann dazu f\xfchren, dass ein Salon Anzahlungen verlangt."],["6. Konten und Beendigung","Du kannst dein Konto jederzeit selbst im Konto-Bereich l\xf6schen; Salons k\xf6nnen ihren Shop selbst trennen. Gesetzliche Aufbewahrungspflichten f\xfcr ausgestellte Belege bleiben beim Salon."],["7. Demo-Hinweis","Diese Installation ist eine Demonstration. Es werden keine echten Zahlungen eingezogen und keine echten Termine vereinbart."]]}};function o(){let{lang:e}=(0,s.Q)(),n=a[e];return(0,i.jsx)(r.O,{title:n.title,lead:n.lead,sections:n.s.map(e=>{let[n,t]=e;return{heading:n,body:(0,i.jsx)("p",{children:t})}})})}},368:function(e,n,t){"use strict";t.d(n,{O:function(){return s}});var i=t(7573);function s(e){let{title:n,lead:t,sections:s,aside:r}=e;return(0,i.jsxs)("div",{className:"info-page",children:[(0,i.jsxs)("header",{className:"info-head",children:[(0,i.jsx)("h1",{children:n}),t&&(0,i.jsx)("p",{className:"info-lead",children:t})]}),r,s.map((e,n)=>(0,i.jsxs)("section",{className:"info-section",children:[e.heading&&(0,i.jsx)("h2",{children:e.heading}),e.body]},n))]})}}},function(e){e.O(0,[36,293,528,744],function(){return e(e.s=3885)}),_N_E=e.O()}]);